import { useEffect, useState } from "react";
import { useAppStore, paneHarness } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { Box } from "@/shared/ui/layout/Box";
import { TerminalSlot } from "@/app/console/terminal/TerminalSlot";
import { BUILTIN_PERSONAS } from "@/features/personas";
import type { PaneKind } from "@/features/tunnel";
import { studioInitCmd, STUDIO_SESSIONS, studioScopeDirective, type StudioId, type StudioSessionDef } from "@/features/studio-sessions/lib/studioSessions";

export function studioStartPrompt(personaId: string): string {
  const fromStore = useAppStore.getState().personas.find((p) => p.id === personaId);
  return (fromStore ?? BUILTIN_PERSONAS.find((p) => p.id === personaId))?.startPrompt ?? "";
}
function tunnelKind(def: StudioSessionDef): PaneKind {
  if (def.role === "designer") return "designer";
  if (def.role === "librarian") return "librarian";
  // The single-technology studios keep their id, which IS a PaneKind member.
  return def.id as PaneKind;
}
/** The session's CONTEXT — who it is and what it owns — written into its CLAUDE.md.
 *
 *  ORDER: identity, then partition. The persona says who it is, the scope says what it owns.
 *
 *  THE ASK DIRECTIVE IS NOT HERE, and that is the fix for
 *  #an-ask-is-delivered-not-left-to-be-found. It used to be appended to this string, so a request the
 *  session was woken to serve was written into a CONTEXT FILE — and the session then launched
 *  `claude --continue`, resumed its previous conversation, and was never prompted with it. The
 *  directive was `take`n on the way past, so it could not be recovered afterwards either. Four real
 *  asks reached their target's CLAUDE.md and nothing else.
 *
 *  Identity is context; an errand is not. The errand goes to `paneStartupPromptText` in
 *  `seedStudioLaunchState`, which is what a harness delivers AS A MESSAGE. */
export function studioContext(def: StudioSessionDef): string {
  const persona = studioStartPrompt(def.personaId);
  return [persona, studioScopeDirective(def)].filter(Boolean).join("\n\n");
}

/** The fields a launch actually needs — everything `seedStudioLaunchState` reads, and nothing else.
 *
 *  WHY THIS IS NOT `StudioSessionDef`. That type is keyed on `StudioId`, a compile-time literal union,
 *  so a session minted at RUNTIME — a network's architect, pane id `network-<slug>:architect` — can
 *  never be one. Narrowing the parameter to what the function reads lets that session share this launch
 *  path rather than forking a second one, and every existing caller passes a `StudioSessionDef`, which
 *  satisfies it unchanged.
 *
 *  `id` is OPTIONAL, and its absence is meaningful rather than a gap: it keys `studioPendingDirective`,
 *  the errand channel `bsc session ask` writes. A network's architect has no such channel today, so it
 *  passes no id and is launched with no errand — which is exactly the `else` branch below, the one that
 *  CLEARS a stale prompt rather than leaving one. */
export type LaunchSeed = Pick<StudioSessionDef, "paneId" | "role" | "personaId" | "defaultSkillIds">
  & { id?: StudioId };

export function seedStudioLaunchState(def: LaunchSeed): string | undefined {
  // NOTHING IS TYPED INTO THE CHAT ANY MORE. `paneStartupPromptText` is baked by `plan_launch` as
  // claude's FIRST MESSAGE, which made the session's identity indistinguishable from the
  // conversation: re-sent every launch, occupying the exchange the user came for, and the first thing
  // a long session forgets. The same prose now goes into the workspace `CLAUDE.md` — composed by
  // `studioContext`, written by the mount below — which is what a harness reads as CONTEXT.
  //
  // It also unblocks RESUME. A startup prompt BEATS `initCmd` in `plan_launch` unless the caller sets
  // `fresh_only`, which no studio ever did — so a studio was re-greeted from scratch on every launch,
  // even when there was a conversation to continue. With no prompt, `studioInitCmd(harness)`
  // (`<harness> --continue || <harness>`) is what runs.
  //
  // The comment that stood here explained the ORDER of the appendices; it moved to `studioContext`.
  //
  //  · the SCOPE (#system-sessions-are-per-technology) — what this session's technology is. Without it
  //    five sessions share one persona and each curates the whole store.
  //  (the ASK DIRECTIVE no longer rides in the CLAUDE.md — see `studioContext`, and the
  //   startup-prompt comment below for where it goes instead.)
  //
  // ORDER: identity, then partition, then the errand. The persona says who it is, the scope says what
  // it owns, the directive says what it was woken for — and the last one is the only one that can be
  // absent, so it goes last and `filter(Boolean)` drops it cleanly.
  // THE ERRAND, taken here rather than in `studioContext` (#an-ask-is-delivered-not-left-to-be-found).
  // Present only when this launch exists to serve an ask. `take`n, not read: a one-shot request must
  // not be resurrected by a later relaunch of the same studio.
  const directive = def.id ? useAppStore.getState().takeStudioPendingDirective(def.id) : undefined;
  useAppStore.setState((st) => {
    // The startup prompt is the ERRAND channel — what `plan_launch` bakes as claude's FIRST MESSAGE.
    // With a directive it carries the request; without one it is CLEARED, not merely left unset,
    // because a pane launched by an older build may still hold a persisted persona greeting under this
    // id and leaving it would re-greet the session exactly as before.
    //
    // THIS DOES NOT COST THE RESUME. `plan_launch` reads
    // `Some(_) => LaunchPlan::Prompt { resume: continue_session && has_history }` — a startup prompt
    // COEXISTS with `--continue`, so a woken studio both continues its conversation and is handed the
    // request it was woken for. Removing the persona greeting from this channel was right (it was
    // re-sent every launch and occupied the exchange the user came for); the errand went with it,
    // which is the bug this restores.
    const startupPrompts = { ...st.paneStartupPromptText };
    if (directive) {
      startupPrompts[def.paneId] = directive;
    } else {
      delete startupPrompts[def.paneId];
    }
    // The studio's CURATED default skills (#3766) — resolved from the library by id, enabled-only. NOT
    // the global firehose; empty when the studio declares no `defaultSkillIds`, so the boundary holds.
    const defaultIds = new Set(def.defaultSkillIds ?? []);
    const defaultSkills = st.skills.filter((sk) => sk.enabled && defaultIds.has(sk.id));
    return {
      paneRoles:             { ...st.paneRoles, [def.paneId]: def.role },
      // …and the persona behind it (epic `the-persona-is-the-whole-agent`), so the launch resolves
      // this studio's capability from its OWN floor rather than from whatever its role happens to
      // carry. Same value `personaId` already supplies for the start prompt.
      panePersonas:          { ...st.panePersonas, [def.paneId]: def.personaId },
      paneStartupPromptText: startupPrompts,
      paneContinue:          { ...st.paneContinue, [def.paneId]: true },
      paneHooks:             { ...st.paneHooks, [def.paneId]: [] },
      paneSkills:            { ...st.paneSkills, [def.paneId]: defaultSkills },
    };
  });
  // RETURNED so the mount can pass it as a PROP. The store write above stays — other panes read it —
  // but it is the losing half of a race here: `TerminalView` reads `paneStartupPromptText` ONCE inside
  // a one-shot launch effect, and this function runs inside an ASYNC effect that has already awaited
  // `setupCommand`. When the read lands first the errand is dropped in silence, and a session with no
  // prompt looks exactly like one that has finished. Measured: a cold-start ask reported the session
  // 'started with your request in its launch prompt' while the process was a bare
  // `claude --model sonnet --continue`. `SlotTerminalProps.startupPrompt` is the route that does not
  // race — the same one `a-debug-session-launches-with-no-charter` had to adopt for the same reason.
  return directive;
}
export function StudioSessionMount({ studio }: { studio: StudioId }) {
  const def = STUDIO_SESSIONS[studio];
  // THE PANE'S OWN HARNESS — see `studioInitCmd`. Hardcoding `claude` here launched the wrong
  // program AND left the session without the run/idle wrapper the backend installs for the
  // harness it was actually given, so the reaper reclaimed it on the short idle grace.
  const harness = useAppStore((s) => paneHarness(s, def.paneId));
  // undefined = still resolving; null = setup failed (no session); string = the workspace cwd.
  // undefined = still resolving; null = setup failed; an object = the launch inputs, together.
  // ONE state value on purpose: the errand has to be in hand at the same render the slot first
  // mounts, and two setState calls could split across renders and launch without it.
  const [launch, setLaunch] = useState<{ cwd: string; errand?: string } | null | undefined>(undefined);

  useEffect(() => {
    let alive = true;
    void (async () => {
      // The studio's global workspace (e.g. ~/.base-studio-code/design-studio/) + its spec CLAUDE.md.
      // The studio's own directory (per TECHNOLOGY where its store is partitioned) and its
      // `CLAUDE.md` — the spec plus this session's context. Written on every open, so a persona edit
      // or a new scope reaches the session on its next launch without a second mechanism.
      const paths = await safeInvoke<Record<string, string> | null>(
        def.setupCommand, { tech: def.tech, context: studioContext(def) }, null,
        (e: unknown) => console.error(`${def.id} workspace setup failed:`, e),
      );
      if (!alive) return;
      const dir = paths?.[def.dirKey];
      if (!dir) { setLaunch(null); return; }
      const errand = seedStudioLaunchState(def);
      // Session roster (#2497): register the studio session so a paired phone lists it alongside the
      // console/fleet/planner panes. Plain store state — useTunnelSync only pushes while the relay runs,
      // so this is inert without a tunnel. Deregistered in the cleanup below.
      useAppStore.getState().registerTunnelPanes(def.id, [{
        id: def.paneId, cwd: dir, name: def.rosterName, status: "running", kind: tunnelKind(def),
      }]);
      setLaunch({ cwd: dir, errand });
    })();
    return () => { alive = false; useAppStore.getState().registerTunnelPanes(def.id, []); };
  }, [def]);

  if (!launch) return null;
  return (
    // Off-screen (NOT display:none, so the parked xterm still fits to a real size) permanent `primary`
    // claim. A visible viewer slot re-parents the terminal out of here when a surface opens it.
    <Box
      aria-hidden
      data-testid={`studio-mount-${def.id}`}
      style={{
        position: "absolute", left: -99999, top: 0, width: 800, height: 600,
        overflow: "hidden", pointerEvents: "none", display: "flex", flexDirection: "column",
      }}
    >
      {/* `parked`: this claim can register at ANY time (its cwd resolves async), so it must never take
          ownership away from a visible dock/morph that claimed first — it owns the terminal only when it
          is the last claim standing. */}
      <TerminalSlot
        paneId={def.paneId}
        primary
        parked
        visible={false}
        initialCwd={launch.cwd}
        initCmd={studioInitCmd(harness)}
        // The errand, handed to the launch rather than left in the store for it to find in time.
        startupPrompt={launch.errand}
      />
    </Box>
  );
}
